import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './SettingsPage.css';

export default function SettingsPage({settings,setSettings,company,setToast}) { return <div className="module-page module-page--settings"><PageTitle eyebrow="WORKSPACE CONFIGURATION" title="Settings & branding" subtitle="Configure the look and defaults for this company workspace."/><div className="settings-layout"><section className="panel settings-form"><div className="panel-head"><div><h3>Brand identity</h3><p>White-label settings preview</p></div></div><label className="settings-label">Company / brand name<input value={settings.companyName} onChange={e=>setSettings({...settings,companyName:e.target.value})}/></label><label className="settings-label">Brand accent color<div className="color-setting"><input type="color" value={settings.brandColor} onChange={e=>setSettings({...settings,brandColor:e.target.value})}/><code>{settings.brandColor}</code></div></label><label className="settings-label">Currency<select value={settings.currency} onChange={e=>setSettings({...settings,currency:e.target.value})}><option value="INR">INR — Indian Rupee</option><option value="USD">USD — US Dollar</option></select></label><label className="settings-label">Timezone<select value={settings.timezone} onChange={e=>setSettings({...settings,timezone:e.target.value})}><option value="Asia/Kolkata">Asia/Kolkata</option><option value="UTC">UTC</option></select></label><button className="btn primary" onClick={()=>setToast('Brand settings saved to Firebase')}>Save workspace settings</button><div className="notice">Brand settings are stored per company in Firestore. Keep tenant access protected by the deployed Firestore rules.</div></section><section className="panel brand-preview"><div className="panel-head"><div><h3>Live brand preview</h3><p>How the company appears in navigation</p></div></div><div className="preview-window"><div className="preview-top"><div className="preview-mark" style={{background:settings.brandColor}}>E+</div><div><b>{settings.companyName||company?.name}</b><small>CRM WORKSPACE</small></div></div><div className="preview-hero" style={{background:`linear-gradient(135deg, ${settings.brandColor}, #171b37)`}}><span>WORKSPACE OVERVIEW</span><h3>Your business,<br/>in one flow.</h3><p>Leads · Team · Property · Growth</p></div><div className="preview-kpis"><div><small>Leads</small><b>128</b></div><div><small>Visits</small><b>16</b></div><div><small>Bookings</small><b>08</b></div></div></div></section></div><section className="panel security-panel"><div className="panel-head"><div><h3>Production readiness checklist</h3><p>Complete these before onboarding paying customers.</p></div><span className="status-pill warning">Not production-ready</span></div>{['Real authentication with password reset and MFA option','Tenant isolation enforced by backend policies','Server-side role and feature permissions','Database backups and tested restore procedure','Subscription billing, plan limits and cancellation handling','Audit log for sensitive changes and exports','Privacy policy, terms, data retention and deletion workflow'].map((x,i)=><div className="checklist-row" key={x}><span className="check-number">{String(i+1).padStart(2,'0')}</span><span>{x}</span><span className="status-pill neutral">Pending</span></div>)}</section></div>; }
